const COOKIE_CONSENT_KEY='abibok-cookie-consent-v1';
const googleConsent=value=>({ad_storage:value,ad_user_data:value,ad_personalization:value,analytics_storage:value});
function readCookieConsent(){try{return localStorage.getItem(COOKIE_CONSENT_KEY)}catch{return null}}
function applyCookieConsent(choice){const value=choice==='granted'?'granted':'denied';try{localStorage.setItem(COOKIE_CONSENT_KEY,value)}catch{}if(typeof window.gtag==='function')window.gtag('consent','update',googleConsent(value));document.documentElement.dataset.adsConsent=value;return value}
window.abibokAdsConsentGranted=()=>readCookieConsent()==='granted';
function initCookieConsent(){
 document.body.insertAdjacentHTML('beforeend','<section class="cookie-banner" role="region" aria-label="Ustawienia cookies" hidden><div><h2>Szanujemy Twój wybór</h2><p>Używamy niezbędnych technologii do działania strony. Opcjonalny Google Ads i pomiar uruchamiamy tylko za Twoją zgodą. <a href="/polityka-cookies/">Polityka cookies</a></p></div><div class="cookie-actions"><button type="button" class="btn btn-primary" data-cookie-choice="granted">Akceptuję</button><button type="button" class="btn btn-primary" data-cookie-choice="denied">Odrzucam</button><button type="button" class="btn btn-secondary" data-cookie-settings>Ustawienia</button></div></section><section class="cookie-modal" role="dialog" aria-modal="true" aria-labelledby="cookie-modal-title" hidden><div class="cookie-modal-card"><h2 id="cookie-modal-title">Opcjonalne cookies i pomiar</h2><label class="cookie-option"><input type="checkbox" data-cookie-optional> <span>Google Ads i pomiar konwersji</span></label><p>Technologie niezbędne pozostają aktywne, aby strona działała i zapamiętała Twój wybór.</p><div class="cookie-actions"><button type="button" class="btn btn-primary" data-cookie-save>Zapisz wybór</button><button type="button" class="btn btn-secondary" data-cookie-cancel>Anuluj</button></div></div></section>');
 const banner=document.querySelector('.cookie-banner'),modal=document.querySelector('.cookie-modal'),optional=modal.querySelector('[data-cookie-optional]');
 const hideModal=()=>{modal.hidden=true};
 const openSettings=()=>{optional.checked=readCookieConsent()==='granted';modal.hidden=false;modal.querySelector('[data-cookie-save]').focus()};
 const finish=choice=>{applyCookieConsent(choice);banner.hidden=true;hideModal()};
 banner.querySelectorAll('[data-cookie-choice]').forEach(button=>button.addEventListener('click',()=>finish(button.dataset.cookieChoice)));
 banner.querySelector('[data-cookie-settings]').addEventListener('click',openSettings);
 document.querySelectorAll('.cookie-settings-link').forEach(button=>button.addEventListener('click',openSettings));
 modal.querySelector('[data-cookie-save]').addEventListener('click',()=>finish(optional.checked?'granted':'denied'));
 modal.querySelector('[data-cookie-cancel]').addEventListener('click',hideModal);
 modal.addEventListener('click',event=>{if(event.target===modal)hideModal()});
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modal.hidden)hideModal()});
 const current=readCookieConsent();if(current==='granted'||current==='denied'){applyCookieConsent(current)}else{banner.hidden=false}
}
function setServiceNote(lang){const service=new URLSearchParams(location.search).get('service'),serviceField=document.querySelector('#service-context');if(!service||!serviceField)return;serviceField.value=service;const serviceNames={'zlota-raczka-warszawa':'Złota rączka Warszawa','drobne-naprawy-warszawa':'Drobne naprawy','drobne-naprawy-hydrauliczne-warszawa':'Drobne naprawy hydrauliczne','drobne-prace-elektryczne-warszawa':'Drobne prace elektryczne','montaz-telewizora-warszawa':'Montaż telewizora','montaz-mebli-warszawa':'Montaż mebli','montaz-polek-karniszy-warszawa':'Półki i karnisze','montaz-i-mocowanie':'Montaż i mocowanie','drobne-naprawy':'Drobne naprawy','meble':'Meble','hydraulika':'Hydraulika','elektryka':'Elektryka','lazienka-i-kuchnia':'Łazienka i kuchnia','okna-i-drzwi':'Okna i drzwi','lista-domowych-spraw':'Lista domowych spraw','bezpieczny-dom':'Bezpieczny dom dla dziecka','nowe-mieszkanie':'Nowe mieszkanie','po-przeprowadzce':'Pomoc po przeprowadzce','regulacja-okien-drzwi-warszawa':'Regulacja okien i drzwi'},sourceName=serviceNames[service]||service.replaceAll('-',' '),localizedName=translations[lang]?.[sourceName]||sourceName,serviceLabel=translations[lang]?.['Wybrany obszar:']||'Wybrany obszar:';document.querySelector('#service-note').textContent=serviceLabel+' '+localizedName}
const originalText=new WeakMap();
function setLanguage(lang){
 if(!['pl','en','ru'].includes(lang))lang='pl';
 document.documentElement.lang=lang;
 try{localStorage.setItem('abibok-lang',lang)}catch{}
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
 let node;
 while((node=walker.nextNode())){
  if(node.parentElement?.closest('script,style'))continue;
  if(!originalText.has(node))originalText.set(node,node.nodeValue);
  const source=originalText.get(node),key=source.trim();
  node.nodeValue=lang==='pl'||!translations[lang]?.[key]?source:source.replace(key,translations[lang][key]);
 }
 document.querySelectorAll('[placeholder],[aria-label]').forEach(element=>{
  for(const attribute of ['placeholder','aria-label']){
   if(!element.hasAttribute(attribute))continue;
   const storageKey='i18n'+attribute.replace('-','');
   if(!element.dataset[storageKey])element.dataset[storageKey]=element.getAttribute(attribute);
   const source=element.dataset[storageKey],translated=translations[lang]?.[source];
   element.setAttribute(attribute,lang==='pl'||!translated?source:translated);
  }
 });
 document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===lang);b.setAttribute('aria-pressed',String(b.dataset.lang===lang))});
 setServiceNote(lang);
 const url=new URL(location.href);if(lang==='pl')url.searchParams.delete('lang');else url.searchParams.set('lang',lang);history.replaceState({},'',url);
}
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.lang)));
initCookieConsent();
let storedLanguage='pl';try{storedLanguage=localStorage.getItem('abibok-lang')||'pl'}catch{}const requestedLanguage=new URLSearchParams(location.search).get('lang')||storedLanguage;setLanguage(requestedLanguage);
const header=document.querySelector('.site-header'),toggle=document.querySelector('.mobile-toggle'),nav=document.querySelector('.nav-links');
addEventListener('scroll',()=>header?.classList.toggle('scrolled',scrollY>8),{passive:true});
toggle?.addEventListener('click',()=>{const open=nav.classList.toggle('open');document.body.classList.toggle('menu-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'×':'☰'});
nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');document.body.classList.remove('menu-open');toggle?.setAttribute('aria-expanded','false');if(toggle)toggle.textContent='☰'}));
document.querySelectorAll('.faq-q').forEach(btn=>btn.addEventListener('click',()=>{const item=btn.closest('.faq-item'),open=item.classList.toggle('open');btn.setAttribute('aria-expanded',String(open));btn.querySelector('span:last-child').textContent=open?'−':'+'}));
const form=document.querySelector('#order-form');
let conversionReported=false;
form?.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const submit=form.querySelector('[type=submit]'),old=submit.textContent;submit.disabled=true;submit.textContent=document.documentElement.lang==='ru'?'Отправка…':document.documentElement.lang==='en'?'Sending…':'Wysyłanie…';try{const response=await fetch('/api/order',{method:'POST',body:new FormData(form)});const result=await response.json();if(!response.ok||result?.ok!==true)throw new Error('send_failed');if(!conversionReported){conversionReported=true;if(typeof window.gtag_report_conversion==='function'){try{window.gtag_report_conversion()}catch(error){console.warn('Google Ads conversion could not be reported',error)}}}form.hidden=true;document.querySelector('.success')?.classList.add('show');document.querySelector('.success')?.focus()}catch{alert(requestedLanguage==='ru'?'Не удалось отправить. Попробуйте ещё раз.':requestedLanguage==='en'?'Could not send. Please try again.':'Nie udało się wysłać. Spróbuj ponownie.')}finally{submit.disabled=false;submit.textContent=old}});
